from typing import List
from functools import lru_cache

class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # Precompute adjacency matrix: adj[i][j] is True if nums[i] and nums[j] are divisible
        adj = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                        adj[i][j] = True

        @lru_cache(None)
        def dp(mask, last):
            if mask == (1 << n) - 1:
                return 1
            total = 0
            for nxt in range(n):
                if not (mask & (1 << nxt)) and adj[last][nxt]:
                    total = (total + dp(mask | (1 << nxt), nxt)) % MOD
            return total

        ans = 0
        for i in range(n):
            ans = (ans + dp(1 << i, i)) % MOD
        return ans
